class UserInvitationWriteRepositoryAdapter implements UserInvitationWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly UserInvitationPdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(UserInvitationRef $ref): ?UserInvitation
    {
        return $this->conn->retrieveForUpdate(new UserInvitationFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?UserInvitationFilter $filter = null, ?UserInvitationCursor $cursor = null): UserInvitationSlide
    {
        $this->logDebug("List for update of User invitation on adapter ");
        $span = $this->startSpan("List for update of User invitation on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new UserInvitationSlide(function (UserInvitationSlide $slide, ?UserInvitationCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new UserInvitationCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(UserInvitationFilter $filter): ?UserInvitation
    {
        $this->logDebug("Retrieve for update of User invitation on adapter ");
        $span = $this->startSpan("Retrieve for update of User invitation on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(UserInvitationFilter $filter): bool
    {
        $this->logDebug("Exists for update of User invitation on adapter ");
        $span = $this->startSpan("Exists for update of User invitation on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?UserInvitationFilter $filter = null): int
    {
        $this->logDebug("Count for update of User invitation on adapter ");
        $span = $this->startSpan("Count for update of User invitation on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(UserInvitation $entity, ?Closure $verify = null): UserInvitation
    {
        $this->logDebug("Count for User invitation on adapter ");
        $span = $this->startSpan("Count for User invitation on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('user-invitation', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(UserInvitationRef $ref, UserInvitation $entity): UserInvitation
